  "امروز یک عکسِ قدیمیِ خوب از دورانِ اولِ رابطه‌تان را با هم ببینید و دربارهٔ آن حرف بزنید.",
  "به‌جایِ «باشه»، امروز واقعاً بپرسید همسرتان چه احساسی دارد و منتظرِ پاسخِ کامل بمانید.",
