  function generatePreviewAnswers(profile) {
    // profile: "healthy" | "moderate" | "critical" — فقط برایِ پیش‌نمایشِ محلی، هیچ‌چیز ذخیره نمی‌شود
    const out = {};
    DOMAINS.forEach((d) => {
      out[d.key] = {};
      d.items.forEach((it, i) => {
        let base;
        if (profile === "healthy") base = it.type === "r" ? 1 + Math.round(Math.random()) : 4 + Math.round(Math.random());
        else if (profile === "critical") base = it.type === "r" ? 4 + Math.round(Math.random()) : 1 + Math.round(Math.random());
        else base = 2 + Math.round(Math.random() * 2); // moderate: 2-4 صرفِ نظر از نوعِ گویه
        out[d.key][i] = Math.min(5, Math.max(1, base));
      });
    });
    return out;
  }
  function previewResults(mode, profile) {
    const a1 = generatePreviewAnswers(profile);
    setAns1(a1);
    setContext({ duration: "بیش از ۱۰ سال", age: "۳۵ تا ۴۴", gender: "زن", children: "یک فرزند" });
    if (mode === "couple") {
      const a2 = generatePreviewAnswers(profile);
      setAns2(a2);
      setCode("PREVIEW");
      setScreen("results");
    } else {
      setAns2({});
      setScreen("soloResult");
    }
  }
